def test_case_insensitive_lookup():
    """Test that plugin lookup is case-insensitive."""
    # Simulate a registered plugin 'Resize'
    registry.lookup = lambda name: registry._registry.get(name.lower())
    registry._registry = {'resize': lambda *args: "resized"}

    # Should work with different cases
    assert plugins.run('resize') == "resized"
    assert plugins.run('Resize') == "resized"
